import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Tests that writeEndArray appends the correct token and correctly
     * moves the write context to the parent when a nested structure exists.
     */
    @Test
    public void testWriteEndArray_WithNestedContext() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Create a nested structure: [ "item" ]
        buffer.writeStartArray();
        buffer.writeString("item");

        // Verify current context is not null and is the array context
        JsonWriteContext contextBefore = buffer.getOutputContext();
        Assert.assertNotNull(contextBefore);

        buffer.writeEndArray();

        // Verify the token appended is END_ARRAY
        // We use a parser to verify the content produced by the buffer
        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        Assert.assertEquals("item", parser.getText());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        Assert.assertNull(parser.nextToken());

        // Verify context movement: the new context should be the parent of the old one
        JsonWriteContext contextAfter = buffer.getOutputContext();
        Assert.assertSame(contextBefore.getParent(), contextAfter);
    }




}

