/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }



    /**
     * Tests that writeEndArray appends the correct token when there is no parent context
     * (i.e., at the root level). This covers the 'if (c != null)' branch where c is null.
     */
    @Test
    public void testWriteEndArray_AtRootLevel() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Write an array at the root level
        buffer.writeStartArray();
        buffer.writeEndArray();

        // Verify the token
        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        Assert.assertNull(parser.nextToken());

        // Verify context: since it was root, the context should remain the same (or not crash)
        // In TokenBuffer, the root context parent is null.
        JsonWriteContext contextAfter = buffer.getOutputContext();
        Assert.assertNull(contextAfter.getParent());
    }


}

package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
