import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }





    /**
     * Tests deep nesting to ensure the context traversal works correctly.
     */
    @Test
    public void testWriteEndArray_DeepNesting() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Structure: [ [ [] ] ]
        buffer.writeStartArray(); // Level 1
        buffer.writeStartArray(); // Level 2
        buffer.writeStartArray(); // Level 3

        JsonWriteContext ctx3 = buffer.getOutputContext();
        JsonWriteContext ctx2 = ctx3.getParent();
        JsonWriteContext ctx1 = ctx2.getParent();

        buffer.writeEndArray(); // Close Level 3
        Assert.assertSame(ctx2, buffer.getOutputContext());

        buffer.writeEndArray(); // Close Level 2
        Assert.assertSame(ctx1, buffer.getOutputContext());

        buffer.writeEndArray(); // Close Level 1

        // Verify structure
        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }
}
